 result=dict(passed=True,state='open_not_finalized',ingestion_ready=False,track2_started=False,counts=dict(counts),analytical_rebuild_max_absolute_error=numeric_error,significant_covariance_psd_violations=psd_violations,minimum_relative_covariance_eigenvalue=minimum_relative_eigenvalue,psd_rounding_tolerance_relative=1e-6,metadata_corrected_videos=metadata_updates,peak_process_tree_rss_gib=max(r['tree_rss_gib'] for r in records),minimum_system_available_gib=min(r['available_gib'] for r in records),oom_observed=False,scope='Numerical and artifact checks on working candidates; no release or scientific acceptance. RSS includes shared mappings. Independent identity/physical-reference validation remains open.',**identity());report('verification.json',result);return result


