 rows=''.join('<tr><td>'+esc(mode)+'</td>'+''.join(f'<td>{r[k]:.4f}</td>' for k in ['iou','boundary_fscore_2px','fscore_scale','fit_seconds'])+'</tr>' for mode,r in sp.items());motion=''.join(f'<tr><td>{esc(name)}</td><td>{r["0.0"]["velocity_rmse_native_px_s"]:.2f}</td><td>{r["0.25"]["position_nrmse"]:.4f}</td><td>{r["0.5"]["position_nrmse"]:.4f}</td></tr>' for name,r in stream.items())
