  rs=[r for r in rows if r['split']==part];result[part]=dict(proposed_protocol_windows=len(rs),supported_protocol_windows=sum(r['supported'] for r in rs),supported_fraction=sum(r['supported'] for r in rs)/len(rs),target_mode_changes=sum(bool(r.get('target_mode_changed')) for r in rs),ambiguous_observation_exclusions=sum(r.get('excluded_matching') or 0 for r in rs))
